  'op.queen.intro': '女王从第一步起就向内冲，抢先占据王座——这是本站引擎最喜欢的开局。\n只有女王冲在前面，若不带卫兵跟上，很容易被夹住。',
  'op.pairs.short': '卫兵两两并进',
  'op.pairs.intro': '先把分散的卫兵靠拢，再两枚一组向内推进。并排的棋子不容易被夹住，也容易形成夹住敌子的形状。\n女王在卫兵之墙后面前往王座。',
  'op.inner.short': '先锋卫兵抢占内圈',
  'op.inner.intro': '让一个卫兵直接走到王座旁（第1圈），抢先占住内圈的格子，同时也能阻挡对方完成包围。\n进入第1圈的卫兵再也出不来，所以要选不会被夹住的位置。',
