  'rv.note': '악수 = 승패가 바뀌거나 크게 손해 본 수. 의문수 = 적지 않은 손해. 판 위의 숫자는 그 칸으로 움직였을 때의 평가(약 1.0 = 한 걸음), 화살표는 최선수, 점선은 실제로 둔 수입니다.',
