  'pz.retry': 'Réfléchissez encore.',
  'pz.reply': 'L’adversaire a répondu {m}. À vous ({n} restants).',
  'pz.th.x2': 'Gagner en deux',
  'pz.th.x2.sub': 'Blancs et Noirs au trait',
