  'cr.hang': 'इस चाल के बाद आपकी {n} गोटी फँस सकती है। <b>{b}</b> सुरक्षित थी।',
  'cr.letThrone': 'इससे विरोधी रानी सिंहासन पर पहुँच गई। <b>{b}</b> से रोका जा सकता था।',
