  'ls.s_block.sub': 'الخانة الأخيرة',
  'ls.s_block.intro': 'سيُكمل الخصم حلقته في النقلة التالية. العب نقلة لا يستطيع بعدها الفوز فورًا — مثلًا بأسر الحارس القادم.',
  'ls.s_block.goal': 'امنع الخصم من إكمال حلقته.',
  'ls.s_block.hint': 'أي حارس للخصم يستطيع دخول الخانة الأخيرة؟ هل يمكنك محاصرته؟',
  'ls.s_block.why': 'صحيح! بعد {m} لا يستطيع الخصم الفوز فورًا.',
  'ls.s_block.ng': 'بعد {m} يُكمل الخصم حلقته في نقلة واحدة.',
  'ls.s_queencap.title': 'الملكة على العرش',
  'ls.s_queencap.sub': 'خانتان متقابلتان',
  'ls.s_queencap.intro': 'حتى الملكة على العرش تُؤسر حين تقف قطعتان لك في خانتين متقابلتين، على خط يمر بالعرش.',
  'ls.s_queencap.goal': 'قم بأسر ملكة الخصم على العرش.',
  'ls.s_queencap.hint': 'على الحلقة 1، انتقل إلى الخانة المقابلة تمامًا لإحدى قطعك عبر العرش.',
  'ls.s_queencap.why': 'صحيح! {m} تطرد الملكة من العرش.',
  'ls.s_queencap.ng': '{m} لا تأسر الملكة.',
  'ls.s_double.title': 'اثنتان دفعة واحدة',
  'ls.s_double.sub': 'إعادتا وضع',
  'ls.s_double.intro': 'حاصر قطعتين بنقلة واحدة، وسيحتاج الخصم دورين لإعادة وضعهما — مكسب كبير.',
  'ls.s_double.goal': 'قم بأسر قطعتين بنقلة واحدة.',
  'ls.s_double.hint': 'خانة تحاصر في اتجاهين في آن واحد.',
  'ls.s_double.why': 'صحيح! {m} تأسر اثنتين.',
  'ls.s_double.ng': '{m} لا تأسر اثنتين.',
  'ls.s_tempo.title': 'أيّها تأسر؟',
  'ls.s_tempo.sub': 'اختيار الأسر',
  'ls.s_tempo.intro': 'هناك عدة أسرات ممكنة. الحارس المتوغل في الداخل يُعاد أبعد إلى الحلقة الخارجية — لكن انظر أيضًا إلى الوضع بعد الأسر.',
  'ls.s_tempo.goal': 'اختر الأسر الأكثر ربحًا.',
  'ls.s_tempo.hint': 'أي حارس أقرب إلى العرش؟ وهل يمكن محاصرة قطعتك بعدها؟',
  'ls.s_tempo.why': 'الأفضل كان {m}.',
  'ls.s_tempo.ng': 'كان هناك أسر أفضل من {m}.',
  'ls.s_win2.title': 'الفوز في نقلتين',
  'ls.s_win2.sub': 'قراءة الدفاع',
  'ls.s_win2.intro': 'نقلتان للفوز — لكن الخصم يلعب بينهما. جد النقلة الأولى التي تفوز مهما كان الرد.',
  'ls.s_win2.goal': 'العب النقلة الأولى لفوز حتمي في نقلتين.',
  'ls.s_win2.hint': 'الملكة أولًا أم الحارس أولًا؟ تجنّب الترتيب الذي يتيح للخصم السد أو المحاصرة.',
  'ls.s_win2.why': 'صحيح! {m} تفوز في نقلتين.',
  'ls.s_win2.ng': 'بعد {m} يصمد الدفاع نقلتين.',
  'ls.s_best.title': 'أفضل نقلة في مباراة حقيقية',
  'ls.s_best.sub': 'تقييم الوضع',
  'ls.s_best.intro': 'أوضاع من مباريات حقيقية. الأسر والدفاع والعرش وإعادة الوضع — وازن بينها كلها وجد أفضل نقلة.',
  'ls.s_best.goal': 'جد أفضل نقلة (نقاط جزئية حسب قيمتها).',
  'ls.s_best.hint': 'تحقق أولًا من القطع المهددة والقطع التي يمكن أسرها.',
  'ls.s_best.why': 'الأفضل كان {m}.',
  'ls.s_best.ng': 'كانت هناك نقلة أفضل من {m}.',
  'op.title': 'خطط الافتتاح',
  'op.desc': 'لم تصلنا تقريبًا أي افتتاحيات مسمّاة في أغون، لذا هذه خطط افتتاح نموذجية يعرضها محرك هذا الموقع. تصفحها نقلة بنقلة في «الدراسة»، ثم خمّن نقلات المحرك في «التدريب».',
  'op.grp.a': 'خطط الافتتاح',
  'op.grp.a.sub': 'الملكة أولًا · جدار من الحراس · السباق على الحلقة الداخلية',
  'op.credit': 'لا تذكر قواعد 1842 ولا كتب القواعد في القرن التاسع عشر أي افتتاحيات. النقلات والتقييمات هنا من محرك هذا الموقع وليست تحليلًا كاملًا.',
  'op.queen.short': 'الملكة مباشرة إلى العرش',
  'op.queen.intro': 'تندفع الملكة إلى الداخل من النقلة الأولى لتأخذ العرش أولًا — الافتتاح المفضل لمحرك هذا الموقع.\nتتقدم الملكة وحدها، فأحضر الحراس خلفها وإلا حوصرت بسهولة.',
  'op.pairs.short': 'الحراس أزواجًا',
  'op.pairs.intro': 'اجمع أولًا الحراس المتفرقين، ثم قدّمهم إلى الداخل اثنين اثنين. يصعب محاصرة الأزواج، ويسهل عليها أن تحاصر.\nتتجه الملكة إلى العرش خلف جدار الحراس.',
  'op.inner.short': 'رأس حربة يأخذ الحلقة الداخلية',
  'op.inner.intro': 'يزحف حارس واحد مباشرة إلى الحلقة 1 بجوار العرش ليأخذ خانة داخلية أولًا — وهذا يسد حلقة الخصم أيضًا.\nالحارس على الحلقة 1 لا يغادرها أبدًا، فاختر خانة لا يمكن محاصرته فيها.',
  'pz.title': 'ألغاز الفوز',
  'pz.desc': 'نهايات حقيقية يتحرك فيها الخصم أيضًا. جد كيف يفرض صاحب الدور الفوز (الملكة على العرش وحولها ستة حراس) خلال عدد النقلات المحدد؛ ويرد الخصم بأعند دفاع للمحرك.',
  'pz.winIn': 'فُز خلال {n}',
  'pz.goal': '{c}: افرض الفوز خلال {n} نقلات (الخصم يدافع)',
  'pz.start': 'العب نقلتك الأولى.',
  'pz.bl.reach': 'أمام أفضل دفاع، لم تعد هذه النقلة تفوز خلال {n} نقلات متبقية.',
  'pz.bl.last': 'هذه النقلة لا تفوز.',
  'pz.best': 'الحل كان {b}.',
  'pz.yourMove': 'نقلة جيدة. دورك (باقي {n} نقلات).',
  'pz.solvedSub': 'فزت في {n} نقلات.',
  'pz.hint1': 'باقي {n} نقلات. عُدّ العرش والخانات الست حوله، ومن أين يدخل الخصم وما يستطيع محاصرته — وجد ترتيبًا لا يستطيع إيقافه.',
  'pz.hintText': 'يبدأ الحل بإحدى القطع المضيئة.',
