  'rv.note': 'Ошибка — ход, который меняет результат или много теряет. Сомнительный — заметная потеря. Числа на доске — ценность хода туда (около 1.0 = один шаг); стрелка — лучший ход, пунктир — сделанный ход.',
  'cr.forced': 'Другого хода не было.',
  'cr.bestCap': 'Лучший ход: взято фигур — {n}; сопернику придётся потратить ход на перестановку.',
