  'intro.players': '2',
  'intro.time': '15–30 分鐘',
  'intro.hist': '1842 年以「Agon, or the Queen’s Guards; a new game of skill」之名在倫敦出版，是<b>已知最古老的六角格棋盤遊戲</b>。據說由安東尼·皮考克設計，Jaques & Son 等維多利亞時代的廠商販售棋盤和棋子。',
  'intro.win': '<b>讓女王坐上中央的王座，並用六名衛兵填滿她周圍的六格</b>即獲勝。棋子沿著所在的圈或往內走，<b>在一直線上被夾住的敵子會被吃掉</b>，必須重新擺到外側。',
  'intro.cult': '棋子永遠不會離開棋盤，所以這是一場搶步數的戰鬥。19 世紀的美國也做過手繪棋盤，House of Marbles 等廠商至今仍在販售。畫在 18 世紀法國遊戲桌上的阿貢棋盤，現在被認為是後來才加上的。',
  'tr.board.t': '棋盤：六個圈和王座',
  'tr.board.b': '棋盤有 91 個六角格：中央是<b>王座</b>，周圍有<b>六個圈</b>（數字是圈的編號：1 緊鄰王座，5 是外圈）。\n開局時雙方的女王和六名衛兵交錯排在外圈。',
  'tr.pieces.t': '棋子：女王與衛兵',
  'tr.pieces.b': '六角形的是<b>女王</b>，圓形的是<b>衛兵</b>（女王有綠框）。走法相同，但<b>只有女王能進入王座</b>，女王被吃時的擺放方式也不同。',
  'tr.step.t': '走法：往內或橫向一步',
  'tr.step.b': '輪到你時，把一枚棋子<b>往相鄰的空格走一步</b>：<b>沿著所在的圈</b>，或<b>進入內側的下一圈</b>。',
  'tr.step.task': '把一名白衛兵往內走一圈。',
  'tr.step.ok': '沒錯 — 圈的編號少了一。',
  'tr.step.ng': '那是沿圈走的一步。這次試著往內走。',
  'tr.noout.t': '絕不往外',
  'tr.noout.b': '棋子<b>絕不能走到外側的圈</b>（紅色箭頭），也不能跳。\n進到內側的棋子就留在內側 — 讓哪枚棋子、在什麼時候進去，非常重要。',
  'tr.throne.t': '王座屬於女王',
  'tr.throne.b': '<b>只有女王</b>能走上王座。衛兵最多只能到王座周圍的第 1 圈。',
  'tr.throne.task': '讓女王走上王座。',
  'tr.throne.ok': '女王坐上王座了！',
  'tr.throne.ng': '讓女王走到王座（中央的格子）。',
  'tr.capture.t': '吃子：在一直線上夾住',
  'tr.capture.b': '移動的棋子和你的另一枚棋子<b>在一直線上夾住一枚敵子</b>時，那枚棋子就<b>被吃</b>。\n被吃的棋子仍留在盤上：持有者<b>下一手必須重新擺放它</b>。',
  'tr.capture.task': '照箭頭走，夾住黑衛兵。',
  'tr.capture.ok': '吃到了！黑方下一手必須花在重新擺放這名衛兵。',
  'tr.capture.ng': '沒有夾住任何棋子。試試箭頭的走法。',
  'tr.reloc.t': '重新擺放：衛兵回到外圈',
  'tr.reloc.b': '你的棋子被吃了（紅色虛線標記），所以這一手是<b>重新擺放</b>，其他棋子不能動。\n<b>被吃的衛兵可擺到外圈（第 5 圈）任一空格</b>。被吃多枚時，一手擺一枚。',
  'tr.reloc.task': '把被吃的衛兵擺到外圈的空格。',
  'tr.reloc.ok': '擺好了 — 它會從這裡再次往內走。',
  'tr.reloc.ng': '請重新擺放被吃的棋子。',
  'tr.qreloc.t': '女王被吃時',
  'tr.qreloc.b': '女王也是同樣被吃。被吃的女王可以擺到<b>王座以外的任一空格</b>（不限外圈）。\n女王和衛兵同時被吃時，<b>先擺女王</b>。',
  'tr.trap.t': '不能走進兩枚敵子之間',
  'tr.trap.b': '棋子<b>不能走進一直線上兩枚敵子之間的格子</b>（× 格）— 不能自己送上門被吃。',
  'tr.trap.task': '移動白衛兵（不能進入 × 格）。',
  'tr.trap.ok': '沒錯 — × 格不能走。',
  'tr.goal.t': '勝利：女王與六名衛兵',
  'tr.goal.b': '當<b>你的女王坐在王座上，周圍六格全是你的衛兵</b>時就獲勝。',
  'tr.goal.task': '把最後一名衛兵帶進來完成包圍。',
  'tr.goal.ok': '完成 — 白方獲勝！',
  'tr.goal.ng': '把最後一名衛兵走進王座周圍的空格。',
  'tr.empty.t': '六名衛兵圍住空王座就輸',
  'tr.empty.b': '如果你的<b>六名衛兵圍住王座，而你的女王不在上面，就立刻判負</b>（否則誰都無法獲勝）。\n五名就位後，在女王坐上王座之前先留住第六名。',
  'tr.vars.t': '另一種開局與和棋',
  'tr.vars.b': '新對局視窗中的「原始布子」是 1842 年的開局方式：<b>一開始只有兩位女王，各在相對的角落</b>，雙方從白方開始輪流把一名衛兵擺到王座以外的任一空格。十二名都擺完後照常對局。\n本站在<b>同一局面出現三次</b>或<b>滿 300 步</b>時判和。',
  'ls.title': '課程',
  'ls.desc': '剛學會規則的人先上「阿貢棋入門」，再用「戰略」學習獲勝。每個步驟約 5 題，每題 20 分，75 分過關。所有答案都經過規則與引擎驗證。',
  'course.basics': '入門',
  'course.basics.sub': '學完規則從這裡開始：往內一步、王座、吃子、重新擺放、防守與收尾。',
  'course.strategy': '戰略',
  'course.strategy.sub': '阻止敵方的圈、吃掉王座上的女王、一次吃兩枚、該吃哪枚、兩步獲勝、實戰最佳著法。',
  'course.graduate': '🎉「入門」完成！可以開始對局了。先試試 Lv.1–6 的 AI。',
  'ls.b_step.title': '往內一步',
