  'ls.b_throne.ng': '{m} tidak membawa ratu ke takhta.',
  'ls.b_capture.title': 'Jepit dan tangkap',
  'ls.b_capture.sub': 'Dalam garis lurus',
  'ls.b_capture.intro': 'Jepit bidak lawan dalam satu garis antara bidak yang kamu gerakkan dan bidakmu yang lain: bidak itu tertangkap dan lawan kehilangan giliran untuk memindahkannya.',
  'ls.b_capture.goal': 'Tangkap satu bidak lawan.',
  'ls.b_capture.hint': 'Cari garis lurus dengan satu bidak lawan di antara dua bidakmu.',
  'ls.b_capture.why': 'Benar! {m} menangkap.',
  'ls.b_capture.ng': '{m} tidak menangkap apa pun.',
  'ls.b_reloc.title': 'Ke mana memindah',
  'ls.b_reloc.sub': 'Pengawal ke tepi',
  'ls.b_reloc.intro': 'Pengawal yang tertangkap dipindah ke petak tepi yang kosong. Pilih petak yang tidak langsung tertangkap lagi dan cepat untuk masuk kembali.',
  'ls.b_reloc.goal': 'Pindahkan pengawal yang tertangkap ke petak tepi terbaik.',
  'ls.b_reloc.hint': 'Hindari petak di antara dua bidak lawan; pilih yang dekat bidakmu dan bisa masuk.',
  'ls.b_reloc.why': 'Yang terbaik {m}.',
  'ls.b_reloc.ng': 'Ada petak yang lebih baik daripada {m}.',
  'ls.b_safe.title': 'Menyelamatkan bidak',
  'ls.b_safe.sub': 'Sebelum terjepit',
  'ls.b_safe.intro': 'Salah satu bidakmu bisa ditangkap oleh langkah lawan berikutnya. Gerakkan, atau isi petak yang akan dipakai lawan.',
  'ls.b_safe.goal': 'Setelah langkahmu, tidak ada bidakmu yang bisa ditangkap.',
  'ls.b_safe.hint': 'Cari dulu ke mana lawan akan bergerak untuk menjepitnya.',
  'ls.b_safe.why': 'Benar! Setelah {m} tidak ada yang bisa ditangkap.',
  'ls.b_safe.ng': 'Setelah {m} masih ada bidak yang bisa dijepit.',
  'ls.b_finish.title': 'Menyelesaikan',
  'ls.b_finish.sub': 'Pengawal keenam',
  'ls.b_finish.intro': 'Ratumu di takhta dengan lima pengawal di sekelilingnya. Masukkan yang terakhir untuk menang.',
  'ls.b_finish.goal': 'Masukkan pengawal terakhir dan menang.',
  'ls.b_finish.hint': 'Cari petak kosong di sekitar takhta dan pengawal di sebelahnya.',
  'ls.b_finish.why': 'Benar! {m} melengkapi cincin — kamu menang.',
  'ls.b_finish.ng': '{m} tidak melengkapinya.',
  'ls.s_block.title': 'Menghentikan cincin lawan',
  'ls.s_block.sub': 'Petak terakhir',
  'ls.s_block.intro': 'Lawan melengkapi cincinnya di langkah berikut. Mainkan langkah yang membuatnya tidak bisa langsung menang — misalnya menangkap pengawal yang akan masuk.',
  'ls.s_block.goal': 'Cegah lawan melengkapi cincinnya.',
  'ls.s_block.hint': 'Pengawal lawan mana yang bisa masuk ke petak terakhir? Bisakah kamu menjepitnya?',
  'ls.s_block.why': 'Benar! Setelah {m} lawan tidak bisa langsung menang.',
  'ls.s_block.ng': 'Setelah {m} lawan melengkapi cincinnya dalam satu langkah.',
  'ls.s_queencap.title': 'Ratu di takhta',
  'ls.s_queencap.sub': 'Dua petak berseberangan',
  'ls.s_queencap.intro': 'Ratu di takhta pun tertangkap jika dua bidakmu berdiri di petak berseberangan, dalam garis yang melewati takhta.',
  'ls.s_queencap.goal': 'Tangkap ratu lawan di takhta.',
  'ls.s_queencap.hint': 'Di cincin 1, bergeraklah ke petak yang berseberangan lurus melewati takhta dari salah satu bidakmu.',
  'ls.s_queencap.why': 'Benar! {m} mengusir ratu dari takhta.',
  'ls.s_queencap.ng': '{m} tidak menangkap ratu.',
  'ls.s_double.title': 'Dua sekaligus',
  'ls.s_double.sub': 'Dua pemindahan',
  'ls.s_double.intro': 'Jepit dua bidak dengan satu langkah dan lawan butuh dua giliran untuk memindahkannya — keuntungan besar.',
  'ls.s_double.goal': 'Tangkap dua bidak dengan satu langkah.',
  'ls.s_double.hint': 'Petak yang menjepit ke dua arah sekaligus.',
  'ls.s_double.why': 'Benar! {m} menangkap dua.',
  'ls.s_double.ng': '{m} tidak menangkap dua.',
  'ls.s_tempo.title': 'Mana yang ditangkap?',
  'ls.s_tempo.sub': 'Memilih penangkapan',
  'ls.s_tempo.intro': 'Beberapa penangkapan mungkin. Pengawal yang sudah jauh di dalam terlempar paling jauh ke tepi — tetapi lihat juga bentuk setelah penangkapan.',
  'ls.s_tempo.goal': 'Pilih penangkapan yang paling menguntungkan.',
  'ls.s_tempo.hint': 'Pengawal mana yang paling dekat takhta? Dan bisakah bidakmu dijepit balik sesudahnya?',
  'ls.s_tempo.why': 'Yang terbaik {m}.',
  'ls.s_tempo.ng': 'Ada penangkapan yang lebih baik daripada {m}.',
  'ls.s_win2.title': 'Menang dalam dua',
  'ls.s_win2.sub': 'Membaca pertahanan',
  'ls.s_win2.intro': 'Dua langkah untuk menang — tetapi lawan bergerak di antaranya. Temukan langkah pertama yang menang apa pun balasannya.',
  'ls.s_win2.goal': 'Mainkan langkah pertama dari kemenangan paksa dalam dua.',
  'ls.s_win2.hint': 'Ratu dulu atau pengawal dulu? Hindari urutan yang membiarkan lawan menghalangi atau menjepit.',
  'ls.s_win2.why': 'Benar! {m} menang dalam dua.',
  'ls.s_win2.ng': 'Setelah {m} pertahanan bertahan dua langkah.',
  'ls.s_best.title': 'Langkah terbaik di permainan nyata',
  'ls.s_best.sub': 'Menilai posisi',
  'ls.s_best.intro': 'Posisi dari permainan nyata. Penangkapan, pertahanan, takhta, pemindahan — timbang semuanya dan temukan langkah terbaik.',
  'ls.s_best.goal': 'Temukan langkah terbaik (poin sebagian sesuai nilainya).',
  'ls.s_best.hint': 'Periksa dulu bidak mana yang terancam dan mana yang bisa ditangkap.',
  'ls.s_best.why': 'Yang terbaik {m}.',
  'ls.s_best.ng': 'Ada langkah yang lebih baik daripada {m}.',
  'op.title': 'Rencana pembukaan',
  'op.desc': 'Hampir tidak ada pembukaan bernama yang diwariskan untuk Agon, jadi berikut rencana pembukaan khas yang ditunjukkan mesin situs ini. Telusuri di “Pelajari”, lalu tebak langkah mesin di “Latihan”.',
  'op.grp.a': 'Rencana pembukaan',
  'op.grp.a.sub': 'Ratu dulu · dinding pengawal · perlombaan ke cincin dalam',
  'op.credit': 'Aturan 1842 dan buku aturan abad ke-19 tidak memuat variasi pembukaan. Langkah dan nilai di sini berasal dari mesin situs ini dan bukan analisis lengkap.',
  'op.queen.short': 'Ratu langsung ke takhta',
  'op.queen.intro': 'Ratu bergerak ke dalam sejak langkah pertama untuk merebut takhta lebih dulu — pembukaan favorit mesin situs ini.\nHanya ratu yang maju, jadi bawa pengawal menyusul atau ia mudah dijepit.',
  'op.pairs.short': 'Pengawal berpasangan',
  'op.pairs.intro': 'Kumpulkan dulu pengawal yang tersebar, lalu masukkan berdua-dua. Pasangan sulit dijepit dan mudah menjepit.\nRatu menuju takhta di balik dinding pengawal.',
  'op.inner.short': 'Ujung tombak merebut cincin dalam',
  'op.inner.intro': 'Satu pengawal berjalan lurus ke cincin 1, di sebelah takhta, untuk merebut petak dalam lebih dulu — sekaligus menghalangi cincin lawan.\nPengawal di cincin 1 tidak bisa keluar lagi, jadi pilih petak yang tidak bisa dijepit.',
  'pz.title': 'Teka-teki menang',
  'pz.desc': 'Permainan akhir nyata di mana lawan juga bergerak. Temukan cara pihak yang melangkah memaksa kemenangan (ratu di takhta, enam pengawal di sekelilingnya) dalam jumlah langkah yang ditentukan; lawan menjawab dengan pertahanan paling gigih dari mesin.',
  'pz.winIn': 'Menang dalam {n}',
  'pz.goal': '{c}: paksa kemenangan dalam {n} langkah (lawan bertahan)',
  'pz.start': 'Mainkan langkah pertamamu.',
