  'pz.solvedSub': 'Menang dalam {n} langkah.',
  'pz.hint1': '{n} langkah lagi. Hitung takhta, enam petak di sekitarnya, di mana lawan bisa masuk dan apa yang bisa ia jepit — dan temukan urutan yang tak bisa ia hentikan.',
  'pz.hintText': 'Solusi dimulai dengan salah satu bidak yang bersinar.',
