  'intro.t': 'Agon nedir?',
  'intro.origin': 'Londra, İngiltere (1842)',
  'intro.players': '2',
  'intro.time': '15–30 dk',
  'intro.hist': '1842\'de Londra\'da “Agon, or the Queen’s Guards; a new game of skill” adıyla yayımlandı; <b>altıgen karelerde oynanan bilinen en eski masa oyunudur</b>. Anthony Peacock\'a atfedilir; Jaques & Son gibi Viktorya dönemi yapımcıları tahta ve taşlarını sattı.',
  'intro.win': '<b>Kraliçeni ortadaki tahta oturt ve çevresindeki altı kareyi altı muhafızınla doldur</b>, kazan. Taşlar halkaları boyunca ya da içeri adım atar; <b>bir çizgide sıkıştırılan rakip taş alınır</b> ve dışarıya yeniden konmalıdır.',
  'intro.cult': 'Hiçbir taş tahtadan ayrılmaz; bu yüzden oyun bir tempo savaşıdır. 19. yüzyıl Amerika\'sında el boyaması tahtalar da yapıldı; House of Marbles gibi yapımcılar hâlâ satıyor. 18. yüzyıl Fransız oyun masalarına boyanmış Agon tahtalarının sonradan eklendiği düşünülüyor.',
  'tr.board.t': 'Tahta: altı halka ve taht',
  'tr.board.b': 'Tahtada 91 altıgen kare var: ortada <b>taht</b>, çevresinde <b>altı halka</b> (sayılar halkalardır: 1 tahtın yanı, 5 kenar).\nBaşta her tarafın kraliçesi ve altı muhafızı kenarda, rakibinkilerle karışık durur.',
  'tr.pieces.t': 'Taşlar: kraliçe ve muhafızlar',
  'tr.pieces.b': 'Altıgen taş <b>kraliçe</b>, yuvarlaklar <b>muhafız</b> (kraliçeler yeşil çerçeveli). Aynı şekilde hareket ederler ama <b>tahta yalnızca kraliçe girebilir</b> ve alınan kraliçe farklı biçimde yeniden konur.',
  'tr.step.t': 'Hareket: bir adım, içeri ya da yana',
  'tr.step.b': 'Sıran gelince bir taşı <b>boş komşu kareye bir adım</b> oynat: <b>halkası boyunca</b> ya da <b>içerideki bir sonraki halkaya</b>.',
  'tr.step.task': 'Bir Beyaz muhafızı bir halka içeri oynat.',
  'tr.step.ok': 'İşte bu — halka numarası bir azaldı.',
  'tr.step.ng': 'Bu halka boyunca bir adımdı. Şimdi içeri bir adım dene.',
  'tr.noout.t': 'Asla dışarı',
  'tr.noout.b': 'Bir taş <b>asla daha dıştaki halkaya gitmez</b> (kırmızı oklar) ve atlama yoktur.\nİçeri giren taş içeride kalır — hangi taşı ne zaman içeri sokacağın önemlidir.',
  'tr.throne.t': 'Taht kraliçenindir',
  'tr.throne.b': 'Tahta <b>yalnızca kraliçe</b> çıkabilir. Muhafızlar en fazla çevresindeki 1. halkaya kadar gider.',
  'tr.throne.task': 'Kraliçeni tahta oynat.',
  'tr.throne.ok': 'Kraliçe tahtta!',
  'tr.throne.ng': 'Kraliçeyi tahta (ortadaki kare) getir.',
  'tr.capture.t': 'Alma: bir çizgide sıkıştır',
  'tr.capture.b': 'Oynattığın taş ve başka bir taşın <b>bir rakip taşı düz bir çizgide sıkıştırınca</b> o taş <b>alınır</b>.\nAlınan taş tahtada kalır: sahibi <b>bir sonraki turda onu yeniden koymak zorundadır</b>.',
  'tr.capture.task': 'Siyah muhafızı sıkıştırmak için oktaki gibi oynat.',
  'tr.capture.ok': 'Alındı! Siyah bir sonraki turunu bu muhafızı yeniden koymaya harcamalı.',
  'tr.capture.ng': 'Çizgide sıkışan taş yok. Oktaki hamleyi dene.',
  'tr.reloc.t': 'Yeniden koyma: muhafız kenara gider',
  'tr.reloc.b': 'Taşın alındı (kırmızı kesikli işaret), bu yüzden bu tur <b>yeniden koyma</b> turudur — başka taş oynatılamaz.\n<b>Alınan muhafız kenardaki (5. halka) herhangi bir boş kareye konur</b>. Birden fazla alındıysa her turda bir tane.',
  'tr.reloc.task': 'Alınan muhafızı kenardaki boş bir kareye koy.',
  'tr.reloc.ok': 'Kondu — buradan yeniden içeri yürür.',
  'tr.reloc.ng': 'Alınan taşı yeniden koy.',
  'tr.qreloc.t': 'Kraliçe alınırsa',
  'tr.qreloc.b': 'Kraliçe de aynı şekilde alınır. Alınan kraliçe <b>tahttan başka herhangi bir boş kareye</b> konabilir (yalnızca kenara değil).\nKraliçe ve muhafız birlikte alındıysa <b>önce kraliçe</b> konur.',
  'tr.trap.t': 'İki rakibin arasına girilmez',
  'tr.trap.b': 'Bir taş <b>bir çizgide iki rakip taşın arasındaki kareye giremez</b> (× kare) — kendini aldıramazsın.',
  'tr.trap.task': 'Beyaz muhafızı oynat (× kareye giremez).',
  'tr.trap.ok': 'Doğru — × kare yasak.',
  'tr.goal.t': 'Galibiyet: kraliçe ve altı muhafız',
  'tr.goal.b': '<b>Kraliçen tahtta otururken çevresindeki altı karenin hepsinde muhafızların</b> olunca kazanırsın.',
  'tr.goal.task': 'Tamamlamak için son muhafızı içeri getir.',
  'tr.goal.ok': 'Tamam — Beyaz kazandı!',
  'tr.goal.ng': 'Son muhafızı tahtın çevresindeki boş kareye oynat.',
  'tr.empty.t': 'Boş tahtın çevresinde altı muhafız kaybeder',
  'tr.empty.b': '<b>Kraliçen tahtta değilken altı muhafızın tahtı çevrelerse hemen kaybedersin</b> (yoksa kimse kazanamazdı).\nBeşi yerindeyken kraliçe tahta oturana dek altıncıyı geride tut.',
  'tr.vars.t': 'Öteki başlangıç ve beraberlik',
  'tr.vars.b': 'Yeni oyun penceresindeki “Özgün diziliş” 1842\'deki başlangıç yoludur: <b>yalnızca kraliçeler karşı köşelerde başlar</b>, oyuncular Beyaz\'dan başlayarak sırayla birer muhafızı tahttan başka boş bir kareye koyar. On ikisi de konunca oyun her zamanki gibi sürer.\nBu sitede <b>aynı konum üç kez oluşursa</b> ya da <b>300 hamleden</b> sonra oyun berabere biter.',
  'ls.title': 'Dersler',
  'ls.desc': 'Kuralları yeni öğrenenler için “Agon\'da ilk adımlar”, sonra kazanmak için “Strateji”. Her adımda yaklaşık 5 soru, her biri 20 puan, 75\'te geçilir. Her cevap kurallar ve motorla doğrulandı.',
  'course.basics': 'İlk adımlar',
  'course.basics.sub': 'Kurallardan sonra buradan başla: içeri adım, taht, alma, yeniden koyma, savunma ve bitiriş.',
  'course.strategy': 'Strateji',
  'course.strategy.sub': 'Rakip halkayı durdurma, tahttaki kraliçeyi alma, çift alma, hangisini almalı, iki hamlede kazanma, gerçek oyunda en iyi hamle.',
  'course.graduate': '🎉 “İlk adımlar” tamam! Oynamaya hazırsın. Önce Lv.1–6 YZ\'yi dene.',
