  'ls.s_queencap.intro': 'Tahttaki kraliçe bile, iki taşın tahttan geçen bir çizgide karşılıklı karelerde durunca alınır.',
  'ls.s_queencap.goal': 'Tahttaki rakip kraliçeyi al.',
