  'ls.s_double.sub': 'İki yeniden koyma',
  'ls.s_double.intro': 'Tek hamlede iki taşı sıkıştır, rakip onları koymak için iki tur harcar — büyük kazanç.',
  'ls.s_double.goal': 'Tek hamlede iki taş al.',
