  'ls.s_tempo.title': 'Hangisini almalı?',
  'ls.s_tempo.sub': 'Alma seçimi',
  'ls.s_tempo.intro': 'Birkaç alma mümkün. Derindeki muhafız kenara en uzağa geri gider — ama almadan sonraki duruma da bak.',
  'ls.s_tempo.goal': 'En kârlı almayı seç.',
  'ls.s_tempo.hint': 'Tahta en yakın muhafız hangisi? Sonrasında taşın geri sıkıştırılabilir mi?',
  'ls.s_tempo.why': 'En iyisi {m} idi.',
  'ls.s_tempo.ng': '{m} hamlesinden daha iyi bir alma vardı.',
  'ls.s_win2.title': 'İki hamlede kazan',
  'ls.s_win2.sub': 'Savunmayı oku',
  'ls.s_win2.intro': 'Kazanmaya iki hamle var — ama arada rakip de oynar. Cevap ne olursa olsun kazandıran ilk hamleyi bul.',
  'ls.s_win2.goal': 'İki hamlede zorunlu galibiyetin ilk hamlesini oyna.',
  'ls.s_win2.hint': 'Önce kraliçe mi muhafız mı? Rakibin kapatabileceği ya da sıkıştırabileceği sıradan kaçın.',
  'ls.s_win2.why': 'Doğru! {m} iki hamlede kazanıyor.',
  'ls.s_win2.ng': '{m} sonrası savunma iki hamle dayanıyor.',
  'ls.s_best.title': 'Gerçek oyunda en iyi hamle',
  'ls.s_best.sub': 'Konumu değerlendir',
  'ls.s_best.intro': 'Gerçek oyunlardan konumlar. Almalar, savunma, taht, yeniden koymalar — hepsini tart ve en iyi hamleyi bul.',
  'ls.s_best.goal': 'En iyi hamleyi bul (değerine göre kısmi puan).',
  'ls.s_best.hint': 'Önce hangi taşların tehlikede, hangilerinin alınabilir olduğuna bak.',
  'ls.s_best.why': 'En iyisi {m} idi.',
  'ls.s_best.ng': '{m} hamlesinden daha iyi bir hamle vardı.',
  'op.title': 'Açılış planları',
  'op.desc': 'Agon için adı konmuş açılış neredeyse hiç günümüze ulaşmadı; burada sitenin motorunun gösterdiği tipik açılış planları var. “Çalış”ta adım adım izle, sonra “Alıştırma”da motorun hamlelerini tahmin et.',
  'op.grp.a': 'Açılış planları',
  'op.grp.a.sub': 'Önce kraliçe · muhafız duvarı · iç halka yarışı',
  'op.credit': '1842 kuralları ve 19. yüzyıl kural kitapları açılış varyantı vermez. Buradaki hamleler ve değerler sitenin motorundan gelir, eksiksiz bir analiz değildir.',
  'op.queen.short': 'Kraliçe doğrudan tahta',
  'op.queen.intro': 'Kraliçe tahtı önce almak için ilk hamleden içeri koşar — sitenin motorunun en sevdiği açılış.\nYalnızca kraliçe öne çıkar; arkasından muhafız getir yoksa kolayca sıkıştırılır.',
  'op.pairs.short': 'Çift çift muhafızlar',
  'op.pairs.intro': 'Önce dağınık muhafızları bir araya getir, sonra ikişer ikişer içeri sok. Çiftleri sıkıştırmak zordur, kendileri de kolayca sıkıştırır.\nKraliçe muhafız duvarının ardından tahta yürür.',
  'op.inner.short': 'Öncü iç halkayı alır',
  'op.inner.intro': 'Bir muhafız iç kareyi önce almak için doğrudan tahtın yanındaki 1. halkaya yürür — rakibin halkasını da engeller.\n1. halkadaki muhafız oradan bir daha çıkamaz; sıkıştırılamayacağı bir kare seç.',
  'pz.title': 'Kazanma bulmacaları',
